// Sitemap index: the single sitemap listed in robots.txt.
import { GetServerSideProps } from 'next';

import {
  fetchShops,
  fetchSpots,
  numChunks,
  sendSitemapIndex,
  SITE_URL,
} from 'lib/sitemap';

export const getServerSideProps: GetServerSideProps = async (ctx) => {
  const [spots, shops] = await Promise.all([fetchSpots(), fetchShops()]);
  const pages = (prefix: string, count: number) =>
    Array.from(
      { length: count },
      (_, i) => `${SITE_URL}/sitemaps/${prefix}-${i + 1}.xml`,
    );

  return sendSitemapIndex(ctx, [
    // static pages, generated by next-sitemap at build time
    `${SITE_URL}/sitemap.xml`,
    ...pages('spots', numChunks(spots)),
    ...pages('shops', numChunks(shops)),
    `${SITE_URL}/sitemaps/locations.xml`,
    `${SITE_URL}/sitemaps/shop-locations.xml`,
  ]);
};

const SitemapNullComponent = () => {};
// Default export to prevent next.js errors
export default SitemapNullComponent;
